TEMPLATE="import itertools\nimport numpy as np\nBG=__BG__\nINK=__INK__\n\n\ndef _variants(grid):\n    a=np.asarray(grid,dtype=int);h,w=a.shape\n    windows=[(y,x) for y in range(h-2) for x in range(w-2) if np.all(a[y:y+3,x:x+3]==BG)]\n    results=[]\n    union=a.copy()\n    for y,x in windows:union[y:y+3,x:x+3]=INK\n    results.append(union)\n    for axis,sy,sx in itertools.product((0,1),(-1,1),(-1,1)):\n        order=sorted(windows,key=lambda p:(sy*p[axis],sx*p[1-axis]))\n        out=a.copy();claimed=np.zeros(a.shape,dtype=bool)\n        for y,x in order:\n            if not np.any(claimed[y:y+3,x:x+3]):\n                out[y:y+3,x:x+3]=INK;claimed[y:y+3,x:x+3]=True\n        results.append(out)\n    return results\n\n\ndef solve(demonstrations,grid):\n    if not demonstrations:raise ValueError('Demonstrations required')\n    alive=set(range(9))\n    for p in demonstrations:\n        options=_variants(p['input'])\n        alive &= {i for i,out in enumerate(options) if np.array_equal(out,np.asarray(p['output']))}\n    if not alive:raise ValueError('No common demonstrated overlap convention')\n    options=_variants(grid);answers=[options[i] for i in alive]\n    if any(not np.array_equal(out,answers[0]) for out in answers[1:]):raise ValueError('Unresolved overlap convention')\n    return answers[0].tolist()\n"

def build_program(d4,palette):
    return TEMPLATE.replace("__BG__",str(int(palette[0]))).replace("__INK__",str(int(palette[1])))
